            raise ValueError(
                f"SID JSON keys must be exactly 0..{len(keys) - 1}; "
                f"got first/last={keys[:2]}...{keys[-2:]}"
            )
        rows = []
        for item_id in keys:
            raw_sid = payload[str(item_id)]
